// Command mikrotik runs the HTTP-to-SOCKS5 proxy gateway.
package main

import (
	"context"
	"errors"
	"log"

	"gitlab.wildberries.ru/pmg/pmg/mikrotik/internal/adapters/httpproxy"
	"gitlab.wildberries.ru/pmg/pmg/mikrotik/internal/adapters/redislimiter"
	"gitlab.wildberries.ru/pmg/pmg/mikrotik/internal/adapters/routejson"
	"gitlab.wildberries.ru/pmg/pmg/mikrotik/internal/adapters/socks5"
	"gitlab.wildberries.ru/pmg/pmg/mikrotik/internal/config"
	"gitlab.wildberries.ru/pmg/pmg/mikrotik/internal/modules/authenticator"
	"gitlab.wildberries.ru/pmg/pmg/mikrotik/internal/modules/bandwidth"
	"gitlab.wildberries.ru/pmg/pmg/mikrotik/internal/modules/routes"
	scratchapp "gitlab.wildberries.ru/wbx-index/platform/scratch/pkg/app"
	scratchredis "gitlab.wildberries.ru/wbx-index/platform/scratch/pkg/database/redis"
	"gitlab.wildberries.ru/wbx-index/platform/scratch/pkg/logger"
)

func main() {
	ctx := context.Background()

	app, err := scratchapp.New(ctx)
	if err != nil {
		log.Fatalf("create Scratch app: %v", err)
	}

	appConfig := app.GetAppConfig(ctx)
	logger.OverrideGlobal(appConfig.GetString(config.LogLevel).Or(logger.DefaultLogLevel))

	initialRoutes, err := routejson.Decode(appConfig.GetString(config.ProxyRoutesJson).Value())
	if err != nil {
		log.Fatalf("create route registry: %v", err)
	}

	routeRegistry := routes.New(initialRoutes)

	connectorPool := socks5.New(socks5.Config{
		Username:              appConfig.GetString(config.Socks5Username).Value(),
		Password:              appConfig.GetString(config.Socks5Password).Value(),
		DialTimeout:           appConfig.GetDuration(config.Socks5DialTimeout).Value(),
		IdleConnTimeout:       appConfig.GetDuration(config.Socks5IdleConnTimeout).Value(),
		ResponseHeaderTimeout: appConfig.GetDuration(config.Socks5ResponseHeaderTimeout).Value(),
		MaxIdleConns:          appConfig.GetInt(config.Socks5MaxIdleConns).Value(),
		MaxIdleConnsPerHost:   appConfig.GetInt(config.Socks5MaxIdleConnsPerHost).Value(),
	})

	if err = appConfig.AddCallback(
		config.ProxyRoutesJson,
		routes.NewRealtimeUpdateCallback(ctx, routeRegistry, connectorPool, routejson.Decode),
	); err != nil {
		log.Fatalf("register route callback: %v", err)
	}

	redisClient, err := scratchredis.NewClient(&scratchredis.Config{
		Addr:         appConfig.GetString(config.RedisAddr).Value(),
		User:         appConfig.GetString(config.RedisUser).Value(),
		Password:     appConfig.GetString(config.RedisPassword).Value(),
		DB:           appConfig.GetInt(config.RedisDb).Value(),
		PoolSize:     appConfig.GetInt(config.RedisPoolSize).Value(),
		MinIdleConns: appConfig.GetInt(config.RedisMinIdleConns).Value(),
		PingTimeout:  appConfig.GetDuration(config.RedisPingTimeout).Value(),
	})
	if err != nil {
		log.Fatalf("connect Redis: %v", err)
	}

	scheduler := redislimiter.New(redisClient)
	pacer := bandwidth.New(scheduler)
	credentials := authenticator.New(appConfig.GetString(config.ProxyAuthPassword).Value())

	proxyServer := httpproxy.New(httpproxy.Config{
		ListenAddress:     appConfig.GetString(config.ProxyListenAddress).Value(),
		ReadHeaderTimeout: appConfig.GetDuration(config.ProxyReadHeaderTimeout).Value(),
		IdleTimeout:       appConfig.GetDuration(config.ProxyIdleTimeout).Value(),
		ShutdownTimeout:   appConfig.GetDuration(config.ProxyShutdownTimeout).Value(),
		MaxHeaderBytes:    appConfig.GetInt(config.ProxyMaxHeaderBytes).Value(),
	}, httpproxy.Dependencies{
		Routes:      routeRegistry,
		Credentials: credentials,
		Limiter:     pacer,
		Connector:   connectorPool,
	})

	scratchapp.Health.AddReadinessCheck("proxy_listener", proxyServer.Ready)

	app.AddCloser(func(closeCtx context.Context) error {
		serverErr := proxyServer.Close(closeCtx)
		connectorPool.Close()
		redisErr := redisClient.Close()

		return errors.Join(serverErr, redisErr)
	})
	if err = app.RunJob(proxyServer.Run); err != nil && !errors.Is(err, context.Canceled) {
		log.Fatalf("run proxy job: %v", err)
	}
}

