1	package httpproxy
2	
3	import (
4		"context"
5		"errors"
6		"io"
7		"net"
8		"sync"
9	
10		"gitlab.wildberries.ru/pmg/pmg/mikrotik/internal/metrics"
11		"gitlab.wildberries.ru/pmg/pmg/mikrotik/internal/models"
12		"gitlab.wildberries.ru/pmg/pmg/mikrotik/internal/types"
13	)
14	
15	// trafficChunkSize bounds each transfer so bandwidth reservations stay small
16	// and pacing remains smooth.
17	const trafficChunkSize = 32 * 1024
18	
19	type pacedCopier struct {
20		route   *models.Route
21		mode    string
22		limiter limiter
23	}
24	
25	func newPacedCopier(route *models.Route, mode string, limiter limiter) *pacedCopier {
26		return &pacedCopier{route: route, mode: mode, limiter: limiter}
27	}
28	
29	func (p *pacedCopier) copy(
30		ctx context.Context,
31		destination io.Writer,
32		source io.Reader,
33		direction types.Direction,
34		flush func(),
35	) error {
36		buffer := make([]byte, trafficChunkSize)
37	
38		for {
39			count, readErr := source.Read(buffer)
40			if count > 0 {
41				if err := p.limiter.Wait(ctx, p.route, direction, count); err != nil {
42					return err
43				}
44	
45				written, writeErr := destination.Write(buffer[:count])
46				if written > 0 {
47					metrics.AddBytes(ctx, p.route.ID, p.mode, direction, int64(written))
48				}
49				if writeErr != nil {
50					return writeErr
51				}
52				if written < count {
53					return io.ErrShortWrite
54				}
55				if flush != nil {
56					flush()
57				}
58			}
59	
60			switch {
61			case errors.Is(readErr, io.EOF):
62				return nil
63			case readErr != nil:
64				return readErr
65			}
66		}
67	}
68	
69	func (p *pacedCopier) wrapBody(
70		ctx context.Context,
71		body io.ReadCloser,
72		direction types.Direction,
73	) io.ReadCloser {
74		return &pacedReadCloser{context: ctx, body: body, copier: p, direction: direction}
75	}
76	
77	type pacedReadCloser struct {
78		context   context.Context
79		body      io.ReadCloser
80		copier    *pacedCopier
81		direction types.Direction
82	}
