package httpproxy

import (
	"context"
	"errors"
	"fmt"
	"net"
	"net/http"
	"sync"
	"sync/atomic"
)

// Server is the public HTTP/1.1 proxy listener with graceful shutdown.
type Server struct {
	cfg          Config
	tunnels      *tunnelSet
	ready        atomic.Bool
	httpServer   *http.Server
	shutdownOnce sync.Once
	shutdownDone chan struct{}
	shutdownErr  error
}

// New builds a Server and its request handler from dependencies.
func New(cfg Config, dependencies Dependencies) *Server {
	tunnels := newTunnelSet()
	server := &Server{
		cfg:          cfg,
		tunnels:      tunnels,
		shutdownDone: make(chan struct{}),
	}

	server.httpServer = &http.Server{
		Addr:              cfg.ListenAddress,
		Handler:           newRequestHandler(dependencies, tunnels),
		ReadHeaderTimeout: cfg.ReadHeaderTimeout,
		IdleTimeout:       cfg.IdleTimeout,
		MaxHeaderBytes:    cfg.MaxHeaderBytes,
	}

	return server
}

// Ready reports whether the listener is accepting connections.
func (s *Server) Ready() error {
	if !s.ready.Load() {
		return errors.New("proxy listener is not ready")
	}

	return nil
}

// Run serves until ctx is canceled or the listener fails.
func (s *Server) Run(ctx context.Context) error {
	listener, err := net.Listen("tcp", s.cfg.ListenAddress)
	if err != nil {
		return fmt.Errorf("listen on %s: %w", s.cfg.ListenAddress, err)
	}

	serveErrors := make(chan error, 1)
	s.ready.Store(true)
	go func() {
		serveErrors <- s.httpServer.Serve(listener)
	}()

	select {
	case <-ctx.Done():
		s.ready.Store(false)
		return s.waitForShutdown()
	case serveErr := <-serveErrors:
		s.ready.Store(false)
		s.tunnels.closeAll()
		if errors.Is(serveErr, http.ErrServerClosed) {
			return nil
		}

		return fmt.Errorf("serve HTTP proxy: %w", serveErr)
	}
}

// Close drains in-flight requests and CONNECT tunnels, then stops serving.
func (s *Server) Close(ctx context.Context) error {
	s.startShutdown()

	select {
	case <-s.shutdownDone:
		return s.shutdownErr
	case <-ctx.Done():
		return ctx.Err()
	}
}

func (s *Server) startShutdown() {
	s.shutdownOnce.Do(func() {
		s.ready.Store(false)
		go func() {
			s.shutdownErr = s.shutdown()
			close(s.shutdownDone)
		}()
	})
}

func (s *Server) waitForShutdown() error {
	s.startShutdown()
	<-s.shutdownDone
	return s.shutdownErr
}

func (s *Server) shutdown() error {
	shutdownCtx, cancel := context.WithTimeout(context.Background(), s.cfg.ShutdownTimeout)
	defer cancel()

	s.tunnels.closeAll()
	shutdownErr := s.httpServer.Shutdown(shutdownCtx)
	if shutdownErr != nil {
		_ = s.httpServer.Close()
	}

	tunnelErr := s.tunnels.waitForClose(shutdownCtx)
	if shutdownErr != nil {
		return fmt.Errorf("shutdown HTTP proxy: %w", shutdownErr)
	}
	if tunnelErr != nil {
		return fmt.Errorf("close CONNECT tunnels: %w", tunnelErr)
	}

	return nil
}

// Package socks5 pools per-route HTTP transports and dials through MikroTik
// SOCKS5 proxies.
package socks5

import (
	"context"
	"fmt"
	"net"
	"net/http"
	"sync"
	"time"

	"gitlab.wildberries.ru/pmg/pmg/mikrotik/internal/metrics"
	"gitlab.wildberries.ru/pmg/pmg/mikrotik/internal/models"
	"golang.org/x/net/proxy"
)

const outcomeConfigurationError = "configuration_error"

// Config tunes dialing and connection reuse towards MikroTik SOCKS5 proxies.
type Config struct {
	Username              string
	Password              string
	DialTimeout           time.Duration
	IdleConnTimeout       time.Duration
	ResponseHeaderTimeout time.Duration
	MaxIdleConns          int
	MaxIdleConnsPerHost   int
}

type transportKey struct {
	routeID string
	address string
}

// Pool keeps one reusable HTTP transport per route and SOCKS5 address.
type Pool struct {
	cfg        Config
	mu         sync.RWMutex
	transports map[transportKey]*http.Transport
}

// New creates an empty Pool with the given dial configuration.
func New(cfg Config) *Pool {
	return &Pool{
		cfg:        cfg,
		transports: make(map[transportKey]*http.Transport),
	}
}

// Transport returns the route's cached RoundTripper, creating it on demand.
func (p *Pool) Transport(route *models.Route) http.RoundTripper {
	key := transportKey{routeID: route.ID, address: route.SOCKS5Address}

	p.mu.RLock()
	existing, ok := p.transports[key]
	p.mu.RUnlock()
	if ok {
		return existing
	}

	p.mu.Lock()
	defer p.mu.Unlock()

	if existing, ok = p.transports[key]; ok {
		return existing
	}

	transport := &http.Transport{
		Proxy: nil,
		DialContext: func(ctx context.Context, _, address string) (net.Conn, error) {
			return p.Dial(ctx, route, address)
		},
		ForceAttemptHTTP2:     false,
		DisableCompression:    true,
		MaxIdleConns:          p.cfg.MaxIdleConns,
		MaxIdleConnsPerHost:   p.cfg.MaxIdleConnsPerHost,
		IdleConnTimeout:       p.cfg.IdleConnTimeout,
		ResponseHeaderTimeout: p.cfg.ResponseHeaderTimeout,
		ExpectContinueTimeout: time.Second,
	}
	p.transports[key] = transport

	return transport
}

// CloseIdle drops idle connections of routes that left the active table.
func (p *Pool) CloseIdle(routes []models.RouteRef) {
	p.mu.Lock()
	defer p.mu.Unlock()

	for _, route := range routes {
		key := transportKey{routeID: route.ID, address: route.SOCKS5Address}
		if transport, ok := p.transports[key]; ok {
			transport.CloseIdleConnections()
			delete(p.transports, key)
		}
	}
}

// Close drops every pooled transport and its idle connections.
func (p *Pool) Close() {
	p.mu.Lock()
	defer p.mu.Unlock()

	for key, transport := range p.transports {
		transport.CloseIdleConnections()
		delete(p.transports, key)
	}
}

// Dial opens a dedicated SOCKS5 connection to destination through the route.
func (p *Pool) Dial(ctx context.Context, route *models.Route, destination string) (net.Conn, error) {
	started := time.Now()
	outcome := "success"
	defer func() {
		metrics.RecordSOCKSDial(ctx, route.ID, outcome, time.Since(started))
	}()

	baseDialer := &net.Dialer{Timeout: p.cfg.DialTimeout}
	socksDialer, err := proxy.SOCKS5(
		"tcp",
		route.SOCKS5Address,
		&proxy.Auth{User: p.cfg.Username, Password: p.cfg.Password},
		baseDialer,
	)
	if err != nil {
		outcome = outcomeConfigurationError
		return nil, fmt.Errorf("create SOCKS5 dialer: %w", err)
	}

	contextDialer, ok := socksDialer.(proxy.ContextDialer)
	if !ok {
		outcome = outcomeConfigurationError
		return nil, fmt.Errorf("SOCKS5 dialer does not support context cancellation")
	}

	connection, err := contextDialer.DialContext(ctx, "tcp", destination)
	if err != nil {
		outcome = "failure"
		return nil, fmt.Errorf("SOCKS5 dial %s: %w", destination, err)
	}

	return connection, nil
}

// Package redislimiter implements globally shared bandwidth scheduling on
// top of Redis.
package redislimiter

import (
	"context"
	"fmt"
	"time"

	"github.com/redis/go-redis/v9"
	"gitlab.wildberries.ru/pmg/pmg/mikrotik/internal/metrics"
	"gitlab.wildberries.ru/pmg/pmg/mikrotik/internal/models"
	"gitlab.wildberries.ru/pmg/pmg/mikrotik/internal/types"
)

const (
	keyPrefix = "mikrotik:bandwidth:v1"
)

// reserveScript implements GCRA (a leaky bucket as a meter). The key stores
// the theoretical arrival time (TAT) in microseconds of Redis server time:
// each chunk advances the TAT by chunk_bytes/rate, and the returned delay
// (TAT minus now minus the burst tolerance) is how long the caller must wait
// before transferring the chunk.
var reserveScript = redis.NewScript(`
local now_parts = redis.call("TIME")
local now = tonumber(now_parts[1]) * 1000000 + tonumber(now_parts[2])
local chunk_bytes = tonumber(ARGV[1])
local rate = tonumber(ARGV[2])
local burst_bytes = tonumber(ARGV[3])

local increment = math.ceil(chunk_bytes * 1000000 / rate)
local burst_tolerance = math.floor(burst_bytes * 1000000 / rate)
local stored = redis.call("GET", KEYS[1])
local tat = now
if stored then
    tat = tonumber(stored)
    if tat < now then
        tat = now
    end
end

local new_tat = tat + increment
local delay = new_tat - now - burst_tolerance
if delay < 0 then
    delay = 0
end

local ttl_ms = math.ceil((new_tat - now + burst_tolerance) / 1000)
if ttl_ms < 1000 then
    ttl_ms = 1000
end
redis.call("SET", KEYS[1], string.format("%.0f", new_tat), "PX", ttl_ms)

return math.ceil(delay)
`)

// Scheduler reserves route bandwidth against the globally shared schedule.
type Scheduler struct {
	client redis.Scripter
}

// New creates a Scheduler on top of a Redis script executor.
func New(client redis.Scripter) *Scheduler {
	return &Scheduler{client: client}
}

// Reserve books bytes on the route's global schedule and returns how long
// the caller must wait before transmitting them.
func (s *Scheduler) Reserve(
	ctx context.Context,
	routeID string,
	direction types.Direction,
	bytes int,
	limits models.RateLimits,
) (time.Duration, error) {
	rate, err := limits.Rate(direction)
	if err != nil {
		return 0, err
	}

	key := reservationKey(routeID, direction, rate, limits.BurstBytes)
	delayMicros, err := reserveScript.Run(
		ctx,
		s.client,
		[]string{key},
		bytes,
		rate,
		limits.BurstBytes,
	).Int64()
	if err != nil {
		metrics.RecordRedisFailure(ctx, "reserve")
		return 0, fmt.Errorf("reserve bandwidth: %w", err)
	}

	return time.Duration(delayMicros) * time.Microsecond, nil
}

// reservationKey embeds the limits so a limits change starts a fresh schedule.
func reservationKey(routeID string, direction types.Direction, rate, burst int64) string {
	return fmt.Sprintf("%s:%s:%s:%d:%d", keyPrefix, routeID, direction, rate, burst)
}

// Package bandwidth paces traffic chunks against bandwidth leased in large
// blocks from a globally shared scheduler, keeping the scheduler (Redis) off
// the per-chunk path.
package bandwidth

import (
	"context"
	"sync"
	"time"

	"gitlab.wildberries.ru/pmg/pmg/mikrotik/internal/metrics"
	"gitlab.wildberries.ru/pmg/pmg/mikrotik/internal/models"
	"gitlab.wildberries.ru/pmg/pmg/mikrotik/internal/types"
)

const (
	// DefaultLeaseBytes is the amount of bandwidth leased from the scheduler
	// in a single reservation.
	DefaultLeaseBytes = 512 * 1024
)

// Scheduler reserves globally shared route bandwidth for local pacing.
type Scheduler interface {
	Reserve(
		ctx context.Context,
		routeID string,
		direction types.Direction,
		bytes int,
		limits models.RateLimits,
	) (time.Duration, error)
}

// Pacer paces per-chunk transfers against locally cached scheduler leases.
type Pacer struct {
	scheduler Scheduler

	mu     sync.RWMutex
	leases map[leaseKey]*lease
}

type leaseKey struct {
	routeID   string
	direction types.Direction
}

type lease struct {
	mu      sync.Mutex
	tat     time.Time // Holds the theoretical arrival time of the next transmitted byte.
	granted int       // Tracks bytes remaining in the current scheduler lease.
}

// New creates a Pacer on top of a bandwidth Scheduler.
func New(scheduler Scheduler) *Pacer {
	return &Pacer{
		scheduler: scheduler,
		leases:    make(map[leaseKey]*lease),
	}
}

// Wait blocks until the given chunk may be transmitted under the route's
// rate limits, reserving more bandwidth from the scheduler when needed.
func (p *Pacer) Wait(
	ctx context.Context,
	route *models.Route,
	direction types.Direction,
	bytes int,
) error {
	if bytes <= 0 {
		return nil
	}

	limits := *route.Limits.Load()
	rate, err := limits.Rate(direction)
	if err != nil {
		return err
	}
	if rate <= 0 {
		return nil
	}

	wait, err := p.schedule(ctx, p.lease(route.ID, direction), route.ID, direction, bytes, rate, limits)
	if err != nil {
		return err
	}
	if wait <= 0 {
		return nil
	}

	metrics.AddThrottleWait(ctx, route.ID, direction, wait)

	timer := time.NewTimer(wait)
	defer timer.Stop()

	select {
	case <-timer.C:
		return nil
	case <-ctx.Done():
		return ctx.Err()
	}
}

func (p *Pacer) lease(routeID string, direction types.Direction) *lease {
	key := leaseKey{routeID: routeID, direction: direction}

	p.mu.RLock()
	existing, ok := p.leases[key]
	p.mu.RUnlock()
	if ok {
		return existing
	}

	p.mu.Lock()
	defer p.mu.Unlock()

	if existing, ok := p.leases[key]; ok {
		return existing
	}

	created := &lease{}
	p.leases[key] = created

	return created
}

func (p *Pacer) schedule(
	ctx context.Context,
	l *lease,
	routeID string,
	direction types.Direction,
	bytes int,
	rate int64,
	limits models.RateLimits,
) (time.Duration, error) {
	l.mu.Lock()
	defer l.mu.Unlock()

	if l.granted < bytes {
		if err := p.refreshGrant(ctx, l, routeID, direction, bytes, rate, limits); err != nil {
			return 0, err
		}
	}
	l.granted -= bytes

	now := time.Now()
	if l.tat.Before(now) {
		l.tat = now
	}
	l.tat = l.tat.Add(durationFor(int64(bytes), rate))

	return l.tat.Sub(now) - durationFor(limits.BurstBytes, rate), nil
}

func (p *Pacer) refreshGrant(
	ctx context.Context,
	l *lease,
	routeID string,
	direction types.Direction,
	minBytes int,
	rate int64,
	limits models.RateLimits,
) error {
	grant := DefaultLeaseBytes
	if grant < minBytes {
		grant = minBytes
	}

	delay, err := p.scheduler.Reserve(ctx, routeID, direction, grant, limits)
	if err != nil {
		return err
	}

	// Fold the global schedule into the local one: this grant occupies
	// the slice of the global schedule that ends at now+delay+burst, so
	// its first byte may transmit once the slice begins.
	start := time.Now().Add(delay + durationFor(limits.BurstBytes, rate) - durationFor(int64(grant), rate))
	if start.After(l.tat) {
		l.tat = start
	}

	l.granted += grant

	return nil
}

func durationFor(bytes, rate int64) time.Duration {
	return time.Duration(float64(bytes) / float64(rate) * float64(time.Second))
}

