// Package routes maintains the active route table and its realtime updates.
package routes

import (
	"sync"
	"sync/atomic"

	"gitlab.wildberries.ru/pmg/pmg/mikrotik/internal/models"
)

// Registry holds the atomically swappable active route table.
type Registry struct {
	updateMu sync.Mutex
	current  atomic.Pointer[models.RouteTable]
}

// New creates a Registry seeded with the initial route table.
func New(initial *models.RouteTable) *Registry {
	registry := &Registry{}
	registry.current.Store(initial)

	return registry
}

// Lookup returns the enabled route with the given ID.
func (r *Registry) Lookup(id string) (*models.Route, bool) {
	value, ok := r.current.Load().Entries[id]
	if !ok || !value.Enabled {
		return nil, false
	}

	return &value.Route, true
}

// Apply swaps the active table, preserving live limit pointers so in-flight
// traffic picks up new limits, and reports which routes need idle cleanup.
func (r *Registry) Apply(table *models.RouteTable) models.RouteChanges {
	r.updateMu.Lock()
	defer r.updateMu.Unlock()

	previous := r.current.Load()
	for id, entry := range table.Entries {
		if old, ok := previous.Entries[id]; ok {
			limits := entry.Route.Limits.Load()
			old.Route.Limits.Store(limits)
			entry.Route.Limits = old.Route.Limits
		}
	}

	changes := diff(previous, table)
	r.current.Store(table)

	return changes
}

func diff(previous, next *models.RouteTable) models.RouteChanges {
	if previous == nil {
		return models.RouteChanges{}
	}

	changes := models.RouteChanges{}
	for id, old := range previous.Entries {
		replacement, exists := next.Entries[id]
		if !exists || !replacement.Enabled || replacement.Route.SOCKS5Address != old.Route.SOCKS5Address {
			changes.CloseIdle = append(changes.CloseIdle, models.RouteRef{
				ID:            old.Route.ID,
				SOCKS5Address: old.Route.SOCKS5Address,
			})
		}
	}

	return changes
}

package routes

import (
	"context"

	"gitlab.wildberries.ru/pmg/pmg/mikrotik/internal/metrics"
	"gitlab.wildberries.ru/pmg/pmg/mikrotik/internal/models"
	"gitlab.wildberries.ru/wbx-index/platform/scratch/pkg/logger"
	"gitlab.wildberries.ru/wbx-index/platform/scratch/pkg/miniyaml"
)

// IdleConnectionCloser drops pooled connections of retired route versions.
type IdleConnectionCloser interface {
	CloseIdle([]models.RouteRef)
}

// RouteTableDecoder parses a raw realtime value into a route table.
type RouteTableDecoder func(string) (*models.RouteTable, error)

// NewRealtimeUpdateCallback validates realtime route updates and applies them
// atomically; invalid snapshots are rejected and the last valid one stays.
func NewRealtimeUpdateCallback(
	ctx context.Context,
	registry *Registry,
	connectorPool IdleConnectionCloser,
	decode RouteTableDecoder,
) func(miniyaml.Node) {
	return func(value miniyaml.Node) {
		raw, ok := value.Value.(string)
		if !ok {
			metrics.RecordRouteReload(ctx, "rejected")
			logger.Error(ctx, "reject realtime route update", "err", "proxy_routes_json is not a string")
			return
		}

		table, err := decode(raw)
		if err != nil {
			metrics.RecordRouteReload(ctx, "rejected")
			logger.Error(ctx, "reject realtime route update", "err", err)
			return
		}

		changes := registry.Apply(table)
		connectorPool.CloseIdle(changes.CloseIdle)
		metrics.RecordRouteReload(ctx, "accepted")
		logger.Info(ctx, "applied realtime route update")
	}
}

// Package models holds the route domain model shared by all packages.
package models

import (
	"fmt"
	"sync/atomic"

	"gitlab.wildberries.ru/pmg/pmg/mikrotik/internal/types"
)

// Default rate limit values applied when a route omits them: 2 Mbit/s in
// each direction and a 64 KiB burst.
const (
	DefaultBytesPerSecond int64 = 2_000_000 / 8
	DefaultBurstBytes     int64 = 64 * 1024
)

// RateLimits caps the bandwidth of a single route in each direction.
type RateLimits struct {
	UploadBytesPerSecond   int64
	DownloadBytesPerSecond int64
	BurstBytes             int64
}

// Rate returns the bandwidth cap for the given traffic direction.
func (l RateLimits) Rate(direction types.Direction) (int64, error) {
	switch direction {
	case types.DirectionUpload:
		return l.UploadBytesPerSecond, nil
	case types.DirectionDownload:
		return l.DownloadBytesPerSecond, nil
	default:
		return 0, fmt.Errorf("unknown traffic direction %q", direction)
	}
}

// Route is a virtual proxy route: clients select it by ID and egress through
// the MikroTik SOCKS5 proxy at SOCKS5Address.
type Route struct {
	ID            string
	SOCKS5Address string
	Limits        *atomic.Pointer[RateLimits]
}

// RouteRef identifies a route version whose idle connections must be dropped.
type RouteRef struct {
	ID            string
	SOCKS5Address string
}

// RouteEntry couples a route with its administrative state.
type RouteEntry struct {
	Route   Route
	Enabled bool
}

// RouteTable is an immutable registry state once published.
type RouteTable struct {
	Entries map[string]*RouteEntry
}

// RouteChanges describes the side effects required after a table swap.
type RouteChanges struct {
	CloseIdle []RouteRef
}

