// Package routejson decodes the versioned JSON route table configuration.
package routejson

import (
	"encoding/json"
	"errors"
	"fmt"
	"net"
	"sync/atomic"

	"gitlab.wildberries.ru/pmg/pmg/mikrotik/internal/models"
)

type routeTable struct {
	Routes []route `json:"routes"`
}

type route struct {
	ID                     string `json:"id"`
	SOCKS5Address          string `json:"socks5_address"`
	Enabled                bool   `json:"enabled"`
	UploadBytesPerSecond   *int64 `json:"upload_bytes_per_second"`
	DownloadBytesPerSecond *int64 `json:"download_bytes_per_second"`
	BurstBytes             *int64 `json:"burst_bytes"`
}

// Decode parses the versioned proxy_routes_json payload into a route table.
func Decode(raw string) (*models.RouteTable, error) {
	var payload routeTable
	if err := json.Unmarshal([]byte(raw), &payload); err != nil {
		return nil, fmt.Errorf("decode route table: %w", err)
	}

	table := models.RouteTable{Entries: make(map[string]*models.RouteEntry, len(payload.Routes))}
	for index, value := range payload.Routes {
		if err := value.validate(); err != nil {
			return nil, fmt.Errorf("route %d (id %q): %w", index, value.ID, err)
		}
		if _, exists := table.Entries[value.ID]; exists {
			return nil, fmt.Errorf("route %d: duplicate id %q", index, value.ID)
		}
		limits := models.RateLimits{
			UploadBytesPerSecond:   models.DefaultBytesPerSecond,
			DownloadBytesPerSecond: models.DefaultBytesPerSecond,
			BurstBytes:             models.DefaultBurstBytes,
		}
		if value.UploadBytesPerSecond != nil {
			limits.UploadBytesPerSecond = *value.UploadBytesPerSecond
		}
		if value.DownloadBytesPerSecond != nil {
			limits.DownloadBytesPerSecond = *value.DownloadBytesPerSecond
		}
		if value.BurstBytes != nil {
			limits.BurstBytes = *value.BurstBytes
		}
		limitsPointer := &atomic.Pointer[models.RateLimits]{}
		limitsPointer.Store(&limits)

		table.Entries[value.ID] = &models.RouteEntry{
			Route: models.Route{
				ID:            value.ID,
				SOCKS5Address: value.SOCKS5Address,
				Limits:        limitsPointer,
			},
			Enabled: value.Enabled,
		}
	}

	return &table, nil
}

func (r route) validate() error {
	if r.ID == "" {
		return errors.New("id is empty")
	}
	if host, port, err := net.SplitHostPort(r.SOCKS5Address); err != nil || host == "" || port == "" {
		return fmt.Errorf("socks5_address %q is not host:port", r.SOCKS5Address)
	}
	if r.UploadBytesPerSecond != nil && *r.UploadBytesPerSecond <= 0 {
		return fmt.Errorf("upload_bytes_per_second %d is not positive", *r.UploadBytesPerSecond)
	}
	if r.DownloadBytesPerSecond != nil && *r.DownloadBytesPerSecond <= 0 {
		return fmt.Errorf("download_bytes_per_second %d is not positive", *r.DownloadBytesPerSecond)
	}
	if r.BurstBytes != nil && *r.BurstBytes < 0 {
		return fmt.Errorf("burst_bytes %d is negative", *r.BurstBytes)
	}

	return nil
}

