// Package authenticator verifies proxy client credentials.
package authenticator

import (
	"crypto/subtle"
	"encoding/base64"
	"strings"
)

const (
	basicPrefix = "Basic "
	realm       = "mikrotik-proxy"
)

// Authenticator verifies proxy Basic credentials against the shared password.
type Authenticator struct {
	password []byte
}

// New creates an Authenticator for the shared proxy password.
func New(password string) *Authenticator {
	return &Authenticator{password: []byte(password)}
}

// Authenticate validates the Proxy-Authorization header and returns the
// username, which carries the requested route ID.
func (a *Authenticator) Authenticate(header string) (string, bool) {
	if len(header) < len(basicPrefix) || !strings.EqualFold(header[:len(basicPrefix)], basicPrefix) {
		return "", false
	}

	decoded, err := base64.StdEncoding.DecodeString(strings.TrimSpace(header[len(basicPrefix):]))
	if err != nil {
		return "", false
	}

	username, password, ok := strings.Cut(string(decoded), ":")
	if !ok || username == "" {
		return "", false
	}

	if subtle.ConstantTimeCompare([]byte(password), a.password) != 1 {
		return "", false
	}

	return username, true
}

// Challenge returns the Proxy-Authenticate header value for 407 responses.
func (a *Authenticator) Challenge() string {
	return `Basic realm="` + realm + `", charset="UTF-8"`
}

