package httpproxy

import (
	"net/http"
	"net/textproto"
	"strings"
)

var hopByHopHeaders = []string{
	"Connection",
	"Proxy-Connection",
	"Keep-Alive",
	"Proxy-Authenticate",
	"Proxy-Authorization",
	"Te",
	"Trailer",
	"Transfer-Encoding",
	"Upgrade",
}

func removeHopByHopHeaders(header http.Header) {
	for _, value := range header.Values("Connection") {
		for token := range strings.SplitSeq(value, ",") {
			name := textproto.TrimString(token)
			if name != "" {
				header.Del(name)
			}
		}
	}

	for _, name := range hopByHopHeaders {
		header.Del(name)
	}
}

func copyHeaders(destination, source http.Header) {
	for name, values := range source {
		for _, value := range values {
			destination.Add(name, value)
		}
	}
}

// Package httpproxy implements the HTTP/1.1 forward proxy front end.
package httpproxy

import (
	"context"
	"net"
	"net/http"
	"time"

	"gitlab.wildberries.ru/pmg/pmg/mikrotik/internal/models"
	"gitlab.wildberries.ru/pmg/pmg/mikrotik/internal/types"
)

type routeRegistry interface {
	Lookup(id string) (*models.Route, bool)
}

type credentials interface {
	Authenticate(header string) (string, bool)
	Challenge() string
}

type limiter interface {
	Wait(ctx context.Context, route *models.Route, direction types.Direction, bytes int) error
}

type connector interface {
	Dial(ctx context.Context, route *models.Route, destination string) (net.Conn, error)
	Transport(route *models.Route) http.RoundTripper
}

// Dependencies wires the request handler to the domain modules.
type Dependencies struct {
	Routes      routeRegistry
	Credentials credentials
	Limiter     limiter
	Connector   connector
}

// Config tunes the underlying HTTP server.
type Config struct {
	ListenAddress     string
	ReadHeaderTimeout time.Duration
	IdleTimeout       time.Duration
	ShutdownTimeout   time.Duration
	MaxHeaderBytes    int
}

// Package types defines small domain primitives shared across packages.
package types

// Direction identifies the flow of proxied traffic relative to the client.
type Direction string

const (
	// DirectionUpload is traffic from the proxy client to the destination.
	DirectionUpload Direction = "upload"
	// DirectionDownload is traffic from the destination to the proxy client.
	DirectionDownload Direction = "download"
)

// Package metrics exposes the service's OpenTelemetry instruments.
package metrics

import (
	"context"
	"fmt"
	"time"

	"gitlab.wildberries.ru/pmg/pmg/mikrotik/internal/types"
	"go.opentelemetry.io/otel"
	"go.opentelemetry.io/otel/attribute"
	"go.opentelemetry.io/otel/metric"
)

const meterName = "mikrotik"

var (
	meter         = otel.Meter(meterName)
	activeTunnels = mustCreate(meter.Int64UpDownCounter("proxy_active_tunnels"))
	outcomes      = mustCreate(meter.Int64Counter("proxy_outcomes_total"))
	bytesCounter  = mustCreate(meter.Int64Counter("proxy_transferred_bytes_total"))
	throttleWait  = mustCreate(meter.Float64Histogram("proxy_throttle_wait_seconds"))
	socksDial     = mustCreate(meter.Float64Histogram("proxy_socks_dial_seconds"))
	routeReloads  = mustCreate(meter.Int64Counter("proxy_route_reloads_total"))
	redisFailures = mustCreate(meter.Int64Counter("proxy_redis_failures_total"))
)

func mustCreate[T any](instrument T, err error) T {
	if err != nil {
		panic(fmt.Errorf("create metric instrument: %w", err))
	}

	return instrument
}

// AddActiveTunnel adjusts the gauge of open CONNECT tunnels for a route.
func AddActiveTunnel(ctx context.Context, routeID string, delta int64) {
	activeTunnels.Add(ctx, delta, metric.WithAttributes(attribute.String("route", routeID)))
}

// RecordOutcome counts a finished proxy request or tunnel by its outcome.
func RecordOutcome(ctx context.Context, routeID, mode, outcome string) {
	outcomes.Add(ctx, 1, metric.WithAttributes(
		attribute.String("route", routeID),
		attribute.String("mode", mode),
		attribute.String("outcome", outcome),
	))
}

// AddBytes counts proxied payload bytes for a route, mode, and direction.
func AddBytes(
	ctx context.Context,
	routeID, mode string,
	direction types.Direction,
	count int64,
) {
	bytesCounter.Add(ctx, count, metric.WithAttributes(
		attribute.String("route", routeID),
		attribute.String("mode", mode),
		attribute.String("direction", string(direction)),
	))
}

// AddThrottleWait records how long a chunk waited on bandwidth pacing.
func AddThrottleWait(
	ctx context.Context,
	routeID string,
	direction types.Direction,
	wait time.Duration,
) {
	throttleWait.Record(ctx, wait.Seconds(), metric.WithAttributes(
		attribute.String("route", routeID),
		attribute.String("direction", string(direction)),
	))
}

// RecordSOCKSDial records the duration and outcome of a SOCKS5 dial.
func RecordSOCKSDial(
	ctx context.Context,
	routeID, outcome string,
	duration time.Duration,
) {
	socksDial.Record(ctx, duration.Seconds(), metric.WithAttributes(
		attribute.String("route", routeID),
		attribute.String("outcome", outcome),
	))
}

// RecordRouteReload counts realtime route table updates by result.
func RecordRouteReload(ctx context.Context, result string) {
	routeReloads.Add(ctx, 1, metric.WithAttributes(attribute.String("result", result)))
}

// RecordRedisFailure counts failed Redis operations by operation name.
func RecordRedisFailure(ctx context.Context, operation string) {
	redisFailures.Add(ctx, 1, metric.WithAttributes(attribute.String("operation", operation)))
}

