240	func stressConnection(
241		ctx context.Context,
242		cfg config,
243		state *connectionState,
244		ready *sync.WaitGroup,
245		start <-chan struct{},
246		results chan<- connectionResult,
247	) {
248		proxyURL := &url.URL{
249			Scheme: "http",
250			Host:   cfg.proxyAddress,
251			User:   url.UserPassword(state.routeID, cfg.proxyPassword),
252		}
253		dialer := &net.Dialer{Timeout: 10 * time.Second, KeepAlive: 30 * time.Second}
254		transport := &http.Transport{
255			Proxy:                 http.ProxyURL(proxyURL),
256			DialContext:           dialer.DialContext,
257			ForceAttemptHTTP2:     true,
258			DisableCompression:    true,
259			MaxIdleConns:          1,
260			MaxIdleConnsPerHost:   1,
261			MaxConnsPerHost:       1,
262			IdleConnTimeout:       cfg.duration + 10*time.Second,
263			TLSHandshakeTimeout:   10 * time.Second,
264			ResponseHeaderTimeout: 15 * time.Second,
265		}
266		client := &http.Client{Transport: transport}
267	
268		ready.Done()
269		<-start
270		started := time.Now()
271		var resultErr error
272		buffer := make([]byte, 256*1024)
273	
274		for ctx.Err() == nil && state.bytes.Load() < state.byteLimit {
275			request, err := http.NewRequestWithContext(ctx, http.MethodGet, cfg.targetURL, nil)
276			if err != nil {
277				resultErr = fmt.Errorf("create request: %w", err)
278				break
279			}
280			request.Header.Set("Accept-Encoding", "identity")
281			request.Header.Set("Range", fmt.Sprintf("bytes=%d-%d", state.rangeStart, state.rangeStart+state.byteLimit-1))
282	
283			response, err := client.Do(request)
284			if err != nil {
285				if ctx.Err() == nil {
286					resultErr = fmt.Errorf("request: %w", err)
287				}
288				break
289			}
290			if response.StatusCode < http.StatusOK || response.StatusCode >= http.StatusMultipleChoices {
291				resultErr = fmt.Errorf("target returned %s", response.Status)
292				_ = response.Body.Close()
293				break
294			}
295	
296			limitReached := false
297			for {
298				remaining := state.byteLimit - state.bytes.Load()
299				if remaining <= 0 {
300					limitReached = true
301					break
302				}
303				readBuffer := buffer
304				if remaining < int64(len(readBuffer)) {
305					readBuffer = readBuffer[:int(remaining)]
306				}
307				count, readErr := response.Body.Read(readBuffer)
308				if count > 0 {
309					state.bytes.Add(int64(count))
310				}
311				if readErr != nil {
312					if !errors.Is(readErr, context.Canceled) && ctx.Err() == nil && !errors.Is(readErr, io.EOF) {
313						resultErr = fmt.Errorf("read response: %w", readErr)
314					}
315					break
316				}
317			}
318			_ = response.Body.Close()
319			state.requests.Add(1)
320			if resultErr != nil || limitReached {
321				break
322			}
323		}
324	
325		transport.CloseIdleConnections()
326		results <- connectionResult{
327			routeID:      state.routeID,
328			connectionID: state.connectionID,
329			byteLimit:    state.byteLimit,
330			bytes:        state.bytes.Load(),
331			requests:     state.requests.Load(),
332			duration:     time.Since(started),
333			err:          resultErr,
334		}
335	}
