337	func recordSamples(outputDirectory string, started time.Time, states []*connectionState, stop <-chan struct{}) error {
338		path := filepath.Join(outputDirectory, "samples.csv")
339		// #nosec G304 -- the output directory is provided by the operator.
340		file, err := os.Create(path)
341		if err != nil {
342			return fmt.Errorf("create samples CSV: %w", err)
343		}
344		defer file.Close()
345	
346		writer := csv.NewWriter(file)
347		defer writer.Flush()
348		if err = writer.Write([]string{"elapsed_seconds", "route_id", "connection_id", "cumulative_bytes", "interval_bytes"}); err != nil {
349			return fmt.Errorf("write samples header: %w", err)
350		}
351	
352		previous := make([]int64, len(states))
353		ticker := time.NewTicker(sampleInterval)
354		defer ticker.Stop()
355		writeSample := func(now time.Time) error {
356			elapsed := now.Sub(started).Seconds()
357			for index, state := range states {
358				current := state.bytes.Load()
359				row := []string{
360					formatFloat(elapsed),
361					state.routeID,
362					strconv.Itoa(state.connectionID),
363					strconv.FormatInt(current, 10),
364					strconv.FormatInt(current-previous[index], 10),
365				}
366				if err := writer.Write(row); err != nil {
367					return err
368				}
369				previous[index] = current
370			}
371			writer.Flush()
372			return writer.Error()
373		}
374	
375		for {
376			select {
377			case now := <-ticker.C:
378				if err := writeSample(now); err != nil {
379					return fmt.Errorf("write traffic sample: %w", err)
380				}
381			case <-stop:
382				if err := writeSample(time.Now()); err != nil {
383					return fmt.Errorf("write final traffic sample: %w", err)
384				}
385				return nil
386			}
387		}
388	}
389	
390	func writeConnectionResults(outputDirectory string, results []connectionResult) error {
391		path := filepath.Join(outputDirectory, "connections.csv")
392		// #nosec G304 -- the output directory is provided by the operator.
393		file, err := os.Create(path)
394		if err != nil {
395			return fmt.Errorf("create connections CSV: %w", err)
396		}
397		defer file.Close()
398	
399		writer := csv.NewWriter(file)
400		defer writer.Flush()
401		if err = writer.Write([]string{
402			"route_id", "connection_id", "byte_limit", "bytes", "mebibytes", "duration_seconds", "requests", "mbps", "error",
403		}); err != nil {
404			return fmt.Errorf("write connections header: %w", err)
405		}
406		for _, result := range results {
407			errorText := ""
408			if result.err != nil {
409				errorText = result.err.Error()
410			}
411			row := []string{
412				result.routeID,
413				strconv.Itoa(result.connectionID),
414				strconv.FormatInt(result.byteLimit, 10),
415				strconv.FormatInt(result.bytes, 10),
416				formatFloat(float64(result.bytes) / (1024 * 1024)),
417				formatFloat(result.duration.Seconds()),
418				strconv.FormatInt(result.requests, 10),
419				formatFloat(megabitsPerSecond(result.bytes, result.duration)),
420				errorText,
421			}
422			if err = writer.Write(row); err != nil {
423				return fmt.Errorf("write connection result: %w", err)
424			}
425		}
426		writer.Flush()
427		if err = writer.Error(); err != nil {
428			return fmt.Errorf("flush connections CSV: %w", err)
429		}
430	
431		return nil
432	}
433	
434	func summarizeRoutes(results []connectionResult) []routeResult {
435		byRoute := make(map[string]*routeResult)
436		for _, result := range results {
437			summary := byRoute[result.routeID]
438			if summary == nil {
439				summary = &routeResult{routeID: result.routeID}
440				byRoute[result.routeID] = summary
441			}
442			summary.connections++
443			summary.byteLimit += result.byteLimit
444			if result.err == nil && result.bytes > 0 {
445				summary.succeeded++
446			}
447			summary.bytes += result.bytes
448			if result.duration > summary.duration {
449				summary.duration = result.duration
450			}
451			throughput := megabitsPerSecond(result.bytes, result.duration)
452			if summary.connections == 1 || throughput < summary.minimumMbps {
453				summary.minimumMbps = throughput
454			}
455			if throughput > summary.maximumMbps {
456				summary.maximumMbps = throughput
457			}
458		}
459	
460		summaries := make([]routeResult, 0, len(byRoute))
461		for _, summary := range byRoute {
462			summaries = append(summaries, *summary)
463		}
464		sort.Slice(summaries, func(i, j int) bool { return summaries[i].routeID < summaries[j].routeID })
465	
466		return summaries
467	}
468	
469	func writeRouteResults(outputDirectory string, results []routeResult) error {
470		path := filepath.Join(outputDirectory, "routes.csv")
471		// #nosec G304 -- the output directory is provided by the operator.
472		file, err := os.Create(path)
473		if err != nil {
474			return fmt.Errorf("create routes CSV: %w", err)
475		}
476		defer file.Close()
477	
478		writer := csv.NewWriter(file)
479		defer writer.Flush()
480		if err = writer.Write([]string{
481			"route_id", "connections", "succeeded", "byte_limit", "bytes", "mebibytes", "duration_seconds", "aggregate_mbps", "minimum_connection_mbps", "maximum_connection_mbps",
482		}); err != nil {
483			return fmt.Errorf("write routes header: %w", err)
484		}
485		for _, result := range results {
486			row := []string{
487				result.routeID,
488				strconv.Itoa(result.connections),
489				strconv.Itoa(result.succeeded),
490				strconv.FormatInt(result.byteLimit, 10),
491				strconv.FormatInt(result.bytes, 10),
492				formatFloat(float64(result.bytes) / (1024 * 1024)),
493				formatFloat(result.duration.Seconds()),
494				formatFloat(megabitsPerSecond(result.bytes, result.duration)),
495				formatFloat(result.minimumMbps),
496				formatFloat(result.maximumMbps),
497			}
498			if err = writer.Write(row); err != nil {
499				return fmt.Errorf("write route result: %w", err)
500			}
501		}
502		writer.Flush()
503		if err = writer.Error(); err != nil {
504			return fmt.Errorf("flush routes CSV: %w", err)
505		}
506	
507		return nil
508	}
509	
510	func printRouteResults(results []routeResult) {
511		fmt.Println("route       connections  succeeded  MiB       aggregate Mbps  min conn Mbps  max conn Mbps")
512		for _, result := range results {
513			fmt.Printf(
514				"%-11s %-12d %-10d %-9.2f %-15.2f %-14.2f %.2f\n",
515				result.routeID,
516				result.connections,
517				result.succeeded,
518				float64(result.bytes)/(1024*1024),
519				megabitsPerSecond(result.bytes, result.duration),
520				result.minimumMbps,
521				result.maximumMbps,
522			)
523		}
524	}
525	
526	func megabitsPerSecond(bytes int64, duration time.Duration) float64 {
527		if duration <= 0 {
528			return 0
529		}
530	
531		return float64(bytes) * 8 / duration.Seconds() / 1_000_000
532	}
533	
534	func formatFloat(value float64) string {
535		return strconv.FormatFloat(value, 'f', 6, 64)
536	}
