	}
	if *duration <= 0 {
		return config{}, errors.New("duration must be positive")
	}

	routeIDs := splitRouteIDs(*routes)
	if len(routeIDs) == 0 {
		return config{}, errors.New("at least one route ID is required")
	}

	return config{
		proxyAddress:        *proxyAddress,
		proxyPassword:       *proxyPassword,
		targetURL:           *targetURL,
		routeIDs:            routeIDs,
		connectionsPerRoute: *connections,
		maxBytesPerRoute:    *maxBytes,
		duration:            *duration,
		outputDirectory:     *outputDirectory,
	}, nil
}

func splitRouteIDs(value string) []string {
	seen := make(map[string]struct{})
	var routeIDs []string
	for routeID := range strings.SplitSeq(value, ",") {
		routeID = strings.TrimSpace(routeID)
		if routeID == "" {
			continue
		}
		if _, exists := seen[routeID]; exists {
			continue
		}
		seen[routeID] = struct{}{}
		routeIDs = append(routeIDs, routeID)
	}
	sort.Strings(routeIDs)

	return routeIDs
}

func run(cfg config) error {
	if err := os.MkdirAll(cfg.outputDirectory, 0o750); err != nil {
		return fmt.Errorf("create output directory: %w", err)
	}

	states := make([]*connectionState, 0, len(cfg.routeIDs)*cfg.connectionsPerRoute)
	for _, routeID := range cfg.routeIDs {
		baseLimit := cfg.maxBytesPerRoute / int64(cfg.connectionsPerRoute)
		extraBytes := cfg.maxBytesPerRoute % int64(cfg.connectionsPerRoute)
		for connectionID := 1; connectionID <= cfg.connectionsPerRoute; connectionID++ {
			connectionIndex := int64(connectionID - 1)
			byteLimit := baseLimit
			if int64(connectionID) <= extraBytes {
				byteLimit++
			}
			rangeStart := connectionIndex * baseLimit
			if connectionIndex < extraBytes {
				rangeStart += connectionIndex
			} else {
				rangeStart += extraBytes
			}
			states = append(states, &connectionState{
				routeID:      routeID,
				connectionID: connectionID,
				rangeStart:   rangeStart,
				byteLimit:    byteLimit,
			})
		}
	}

	ctx, cancel := context.WithTimeout(context.Background(), cfg.duration)
	defer cancel()

	ready := sync.WaitGroup{}
	ready.Add(len(states))
	start := make(chan struct{})
	results := make(chan connectionResult, len(states))
	for _, state := range states {
		go stressConnection(ctx, cfg, state, &ready, start, results)
	}

	ready.Wait()
	started := time.Now()
	close(start)

	stopSamples := make(chan struct{})
	samplesDone := make(chan error, 1)
	go func() {
		samplesDone <- recordSamples(cfg.outputDirectory, started, states, stopSamples)
	}()

	connectionResults := make([]connectionResult, 0, len(states))
	for range states {
		connectionResults = append(connectionResults, <-results)
	}
	close(stopSamples)
	if err := <-samplesDone; err != nil {
		return err
	}

	sort.Slice(connectionResults, func(i, j int) bool {
		if connectionResults[i].routeID == connectionResults[j].routeID {
			return connectionResults[i].connectionID < connectionResults[j].connectionID
		}
		return connectionResults[i].routeID < connectionResults[j].routeID
	})

	if err := writeConnectionResults(cfg.outputDirectory, connectionResults); err != nil {
		return err
	}
	routeResults := summarizeRoutes(connectionResults)
	if err := writeRouteResults(cfg.outputDirectory, routeResults); err != nil {
		return err
	}
	printRouteResults(routeResults)

	failed := 0
	for _, result := range connectionResults {
		if result.err != nil || result.bytes == 0 {
			failed++
		}
	}
	if failed > 0 {
		return fmt.Errorf("%d of %d connections failed; inspect %s", failed, len(connectionResults), filepath.Join(cfg.outputDirectory, "connections.csv"))
	}

	return nil
}

func stressConnection(
	ctx context.Context,
	cfg config,
	state *connectionState,
	ready *sync.WaitGroup,
	start <-chan struct{},
	results chan<- connectionResult,
) {
	proxyURL := &url.URL{
		Scheme: "http",
		Host:   cfg.proxyAddress,
		User:   url.UserPassword(state.routeID, cfg.proxyPassword),
	}
	dialer := &net.Dialer{Timeout: 10 * time.Second, KeepAlive: 30 * time.Second}
	transport := &http.Transport{
		Proxy:                 http.ProxyURL(proxyURL),
		DialContext:           dialer.DialContext,
		ForceAttemptHTTP2:     true,
		DisableCompression:    true,
		MaxIdleConns:          1,
		MaxIdleConnsPerHost:   1,
		MaxConnsPerHost:       1,
		IdleConnTimeout:       cfg.duration + 10*time.Second,
		TLSHandshakeTimeout:   10 * time.Second,
		ResponseHeaderTimeout: 15 * time.Second,
	}
	client := &http.Client{Transport: transport}

	ready.Done()
	<-start
	started := time.Now()
	var resultErr error
	buffer := make([]byte, 256*1024)

	for ctx.Err() == nil && state.bytes.Load() < state.byteLimit {
		request, err := http.NewRequestWithContext(ctx, http.MethodGet, cfg.targetURL, nil)
		if err != nil {
			resultErr = fmt.Errorf("create request: %w", err)
			break
		}
		request.Header.Set("Accept-Encoding", "identity")
		request.Header.Set("Range", fmt.Sprintf("bytes=%d-%d", state.rangeStart, state.rangeStart+state.byteLimit-1))

		response, err := client.Do(request)
		if err != nil {
			if ctx.Err() == nil {
				resultErr = fmt.Errorf("request: %w", err)
			}
			break
		}
		if response.StatusCode < http.StatusOK || response.StatusCode >= http.StatusMultipleChoices {
			resultErr = fmt.Errorf("target returned %s", response.Status)
			_ = response.Body.Close()
			break
		}

		limitReached := false
		for {
			remaining := state.byteLimit - state.bytes.Load()
			if remaining <= 0 {
				limitReached = true
				break
			}
			readBuffer := buffer
			if remaining < int64(len(readBuffer)) {
				readBuffer = readBuffer[:int(remaining)]
			}
			count, readErr := response.Body.Read(readBuffer)
			if count > 0 {
				state.bytes.Add(int64(count))
			}
			if readErr != nil {
				if !errors.Is(readErr, context.Canceled) && ctx.Err() == nil && !errors.Is(readErr, io.EOF) {
					resultErr = fmt.Errorf("read response: %w", readErr)
				}
				break
			}
		}
		_ = response.Body.Close()
		state.requests.Add(1)
		if resultErr != nil || limitReached {
			break
		}
	}

	transport.CloseIdleConnections()
	results <- connectionResult{
		routeID:      state.routeID,
		connectionID: state.connectionID,
		byteLimit:    state.byteLimit,
		bytes:        state.bytes.Load(),
		requests:     state.requests.Load(),
		duration:     time.Since(started),
		err:          resultErr,
	}
}

func recordSamples(outputDirectory string, started time.Time, states []*connectionState, stop <-chan struct{}) error {
	path := filepath.Join(outputDirectory, "samples.csv")
	// #nosec G304 -- the output directory is provided by the operator.
	file, err := os.Create(path)
	if err != nil {
		return fmt.Errorf("create samples CSV: %w", err)
	}
	defer file.Close()

	writer := csv.NewWriter(file)
	defer writer.Flush()
	if err = writer.Write([]string{"elapsed_seconds", "route_id", "connection_id", "cumulative_bytes", "interval_bytes"}); err != nil {
		return fmt.Errorf("write samples header: %w", err)
	}

	previous := make([]int64, len(states))
	ticker := time.NewTicker(sampleInterval)
	defer ticker.Stop()
	writeSample := func(now time.Time) error {
		elapsed := now.Sub(started).Seconds()
		for index, state := range states {
			current := state.bytes.Load()
			row := []string{
				formatFloat(elapsed),
				state.routeID,
				strconv.Itoa(state.connectionID),
				strconv.FormatInt(current, 10),
				strconv.FormatInt(current-previous[index], 10),
			}
			if err := writer.Write(row); err != nil {
				return err
			}
			previous[index] = current
		}
		writer.Flush()
		return writer.Error()
	}

	for {
		select {
		case now := <-ticker.C:
			if err := writeSample(now); err != nil {
				return fmt.Errorf("write traffic sample: %w", err)
			}
		case <-stop:
			if err := writeSample(time.Now()); err != nil {
				return fmt.Errorf("write final traffic sample: %w", err)
			}
			return nil
		}
	}
}

func writeConnectionResults(outputDirectory string, results []connectionResult) error {
	path := filepath.Join(outputDirectory, "connections.csv")
	// #nosec G304 -- the output directory is provided by the operator.
	file, err := os.Create(path)
	if err != nil {
		return fmt.Errorf("create connections CSV: %w", err)
	}
	defer file.Close()

	writer := csv.NewWriter(file)
	defer writer.Flush()
	if err = writer.Write([]string{
		"route_id", "connection_id", "byte_limit", "bytes", "mebibytes", "duration_seconds", "requests", "mbps", "error",
	}); err != nil {
		return fmt.Errorf("write connections header: %w", err)
	}
	for _, result := range results {
		errorText := ""
		if result.err != nil {
			errorText = result.err.Error()
		}
		row := []string{
			result.routeID,
			strconv.Itoa(result.connectionID),
			strconv.FormatInt(result.byteLimit, 10),
			strconv.FormatInt(result.bytes, 10),
			formatFloat(float64(result.bytes) / (1024 * 1024)),
			formatFloat(result.duration.Seconds()),
			strconv.FormatInt(result.requests, 10),
			formatFloat(megabitsPerSecond(result.bytes, result.duration)),
			errorText,
		}
		if err = writer.Write(row); err != nil {
			return fmt.Errorf("write connection result: %w", err)
		}
	}
	writer.Flush()
	if err = writer.Error(); err != nil {
		return fmt.Errorf("flush connections CSV: %w", err)
	}

	return nil
}

func summarizeRoutes(results []connectionResult) []routeResult {
	byRoute := make(map[string]*routeResult)
	for _, result := range results {
		summary := byRoute[result.routeID]
		if summary == nil {
			summary = &routeResult{routeID: result.routeID}
			byRoute[result.routeID] = summary
		}
		summary.connections++
		summary.byteLimit += result.byteLimit
		if result.err == nil && result.bytes > 0 {
			summary.succeeded++
		}
		summary.bytes += result.bytes
		if result.duration > summary.duration {
			summary.duration = result.duration
		}
		throughput := megabitsPerSecond(result.bytes, result.duration)
		if summary.connections == 1 || throughput < summary.minimumMbps {
			summary.minimumMbps = throughput
		}
		if throughput > summary.maximumMbps {
			summary.maximumMbps = throughput
		}
	}

	summaries := make([]routeResult, 0, len(byRoute))
	for _, summary := range byRoute {
		summaries = append(summaries, *summary)
	}
	sort.Slice(summaries, func(i, j int) bool { return summaries[i].routeID < summaries[j].routeID })

	return summaries
}

func writeRouteResults(outputDirectory string, results []routeResult) error {
	path := filepath.Join(outputDirectory, "routes.csv")
	// #nosec G304 -- the output directory is provided by the operator.
	file, err := os.Create(path)
	if err != nil {
		return fmt.Errorf("create routes CSV: %w", err)
	}
	defer file.Close()

	writer := csv.NewWriter(file)
	defer writer.Flush()
	if err = writer.Write([]string{
		"route_id", "connections", "succeeded", "byte_limit", "bytes", "mebibytes", "duration_seconds", "aggregate_mbps", "minimum_connection_mbps", "maximum_connection_mbps",
	}); err != nil {
		return fmt.Errorf("write routes header: %w", err)
	}
	for _, result := range results {
		row := []string{
			result.routeID,
			strconv.Itoa(result.connections),
			strconv.Itoa(result.succeeded),
			strconv.FormatInt(result.byteLimit, 10),
			strconv.FormatInt(result.bytes, 10),
			formatFloat(float64(result.bytes) / (1024 * 1024)),
			formatFloat(result.duration.Seconds()),
			formatFloat(megabitsPerSecond(result.bytes, result.duration)),
			formatFloat(result.minimumMbps),
			formatFloat(result.maximumMbps),
		}
		if err = writer.Write(row); err != nil {
			return fmt.Errorf("write route result: %w", err)
		}
	}
	writer.Flush()
	if err = writer.Error(); err != nil {
		return fmt.Errorf("flush routes CSV: %w", err)
	}

	return nil
}

func printRouteResults(results []routeResult) {
	fmt.Println("route       connections  succeeded  MiB       aggregate Mbps  min conn Mbps  max conn Mbps")
	for _, result := range results {
		fmt.Printf(
			"%-11s %-12d %-10d %-9.2f %-15.2f %-14.2f %.2f\n",
			result.routeID,
			result.connections,
			result.succeeded,
			float64(result.bytes)/(1024*1024),
			megabitsPerSecond(result.bytes, result.duration),
			result.minimumMbps,
			result.maximumMbps,
		)
	}
}

func megabitsPerSecond(bytes int64, duration time.Duration) float64 {
	if duration <= 0 {
		return 0
	}

	return float64(bytes) * 8 / duration.Seconds() / 1_000_000
}

func formatFloat(value float64) string {
	return strconv.FormatFloat(value, 'f', 6, 64)
}

