package routejson

import (
	"strings"
	"testing"

	"gitlab.wildberries.ru/pmg/pmg/mikrotik/internal/models"
)

func TestDecodeAppliesDefaultsAndOverrides(t *testing.T) {
	raw := `{"routes": [
		{"id": "plain", "socks5_address": "10.0.0.1:1080", "enabled": true},
		{"id": "tuned", "socks5_address": "10.0.0.2:1080", "enabled": false,
			"upload_bytes_per_second": 100, "download_bytes_per_second": 200, "burst_bytes": 0}
	]}`

	table, err := Decode(raw)
	if err != nil {
		t.Fatalf("Decode: %v", err)
	}
	if len(table.Entries) != 2 {
		t.Fatalf("expected 2 entries, got %d", len(table.Entries))
	}

	plain := table.Entries["plain"].Route.Limits.Load()
	if plain.UploadBytesPerSecond != models.DefaultBytesPerSecond ||
		plain.DownloadBytesPerSecond != models.DefaultBytesPerSecond ||
		plain.BurstBytes != models.DefaultBurstBytes {
		t.Errorf("expected default limits, got %+v", *plain)
	}

	tuned := table.Entries["tuned"].Route.Limits.Load()
	if tuned.UploadBytesPerSecond != 100 || tuned.DownloadBytesPerSecond != 200 || tuned.BurstBytes != 0 {
		t.Errorf("expected overridden limits, got %+v", *tuned)
	}
	if table.Entries["tuned"].Enabled {
		t.Error("expected tuned route to be disabled")
	}
}

func TestDecodeRejectsInvalidRoutes(t *testing.T) {
	tests := []struct {
		name    string
		raw     string
		wantErr string
	}{
		{
			name:    "malformed json",
			raw:     `{"routes": [`,
			wantErr: "decode route table",
		},
		{
			name:    "empty id",
			raw:     `{"routes": [{"id": "", "socks5_address": "10.0.0.1:1080"}]}`,
			wantErr: "id is empty",
		},
		{
			name: "duplicate id",
			raw: `{"routes": [
				{"id": "a", "socks5_address": "10.0.0.1:1080"},
				{"id": "a", "socks5_address": "10.0.0.2:1080"}
			]}`,
			wantErr: `duplicate id "a"`,
		},
		{
			name:    "missing socks5 address",
			raw:     `{"routes": [{"id": "a"}]}`,
			wantErr: "is not host:port",
		},
		{
			name:    "socks5 address without port",
			raw:     `{"routes": [{"id": "a", "socks5_address": "10.0.0.1"}]}`,
			wantErr: "is not host:port",
		},
		{
			name:    "zero upload rate",
			raw:     `{"routes": [{"id": "a", "socks5_address": "10.0.0.1:1080", "upload_bytes_per_second": 0}]}`,
			wantErr: "upload_bytes_per_second 0 is not positive",
		},
		{
			name:    "negative download rate",
			raw:     `{"routes": [{"id": "a", "socks5_address": "10.0.0.1:1080", "download_bytes_per_second": -1}]}`,
			wantErr: "download_bytes_per_second -1 is not positive",
		},
		{
			name:    "negative burst",
			raw:     `{"routes": [{"id": "a", "socks5_address": "10.0.0.1:1080", "burst_bytes": -1}]}`,
			wantErr: "burst_bytes -1 is negative",
		},
	}

	for _, test := range tests {
		t.Run(test.name, func(t *testing.T) {
			_, err := Decode(test.raw)
			if err == nil {
				t.Fatal("expected error, got nil")
			}
			if !strings.Contains(err.Error(), test.wantErr) {
				t.Fatalf("expected error containing %q, got %q", test.wantErr, err)
			}
		})
	}
}

