1	package main
2	
3	import (
4		"encoding/json"
5		"fmt"
6		"net"
7		"os"
8		"strconv"
9	
10		pb "gitlab.wildberries.ru/pmg/pmg/etcdservice/pkg/pb/etcdservice"
11		"gitlab.wildberries.ru/pmg/pmg/mikrotik/internal/modules/routes"
12		"gitlab.wildberries.ru/wbx-index/platform/scratch/pkg/miniyaml"
13		"google.golang.org/grpc"
14	)
15	
16	const defaultAddress = "0.0.0.0:19049"
17	
18	type realtimeServer struct {
19		pb.UnimplementedEtcdServiceServer
20	}
21	
22	func main() {
23		listener, err := net.Listen("tcp", defaultAddress)
24		if err != nil {
25			_, _ = fmt.Fprintln(os.Stderr, err)
26			os.Exit(1)
27		}
28	
29		server := grpc.NewServer()
30		pb.RegisterEtcdServiceServer(server, realtimeServer{})
31		if err = server.Serve(listener); err != nil {
32			_, _ = fmt.Fprintln(os.Stderr, err)
33			os.Exit(1)
34		}
35	}
36	
37	func (realtimeServer) RealtimeConfiguration(
38		stream pb.EtcdService_RealtimeConfigurationServer,
39	) error {
40		if _, err := stream.Recv(); err != nil {
41			return err
42		}
43	
44		node := &miniyaml.Node{Value: routeTable()}
45		if err := stream.Send(&pb.RealtimeConfigurationResponse{
46			Values: []*pb.Value{{
47				Name:  "proxy_routes_json",
48				Value: node.Canonical(),
49			}},
50		}); err != nil {
51			return err
52		}
53	
54		<-stream.Context().Done()
55		return stream.Context().Err()
56	}
57	
58	func routeTable() string {
59		rateText := os.Getenv("ROUTE_RATE_BYTES_PER_SECOND")
60		burstText := os.Getenv("ROUTE_BURST_BYTES")
61		if rateText == "" || burstText == "" {
62			return routes.DefaultJSON
63		}
64	
65		rate, err := strconv.ParseInt(rateText, 10, 64)
66		if err != nil {
67			panic(err)
68		}
69		burst, err := strconv.ParseInt(burstText, 10, 64)
70		if err != nil {
71			panic(err)
72		}
73	
74		var table struct {
