package main

import (
	"encoding/json"
	"fmt"
	"net"
	"os"
	"strconv"

	pb "gitlab.wildberries.ru/pmg/pmg/etcdservice/pkg/pb/etcdservice"
	"gitlab.wildberries.ru/pmg/pmg/mikrotik/internal/modules/routes"
	"gitlab.wildberries.ru/wbx-index/platform/scratch/pkg/miniyaml"
	"google.golang.org/grpc"
)

const defaultAddress = "0.0.0.0:19049"

type realtimeServer struct {
	pb.UnimplementedEtcdServiceServer
}

func main() {
	listener, err := net.Listen("tcp", defaultAddress)
	if err != nil {
		_, _ = fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}

	server := grpc.NewServer()
	pb.RegisterEtcdServiceServer(server, realtimeServer{})
	if err = server.Serve(listener); err != nil {
		_, _ = fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
}

func (realtimeServer) RealtimeConfiguration(
	stream pb.EtcdService_RealtimeConfigurationServer,
) error {
	if _, err := stream.Recv(); err != nil {
		return err
	}

	node := &miniyaml.Node{Value: routeTable()}
	if err := stream.Send(&pb.RealtimeConfigurationResponse{
		Values: []*pb.Value{{
			Name:  "proxy_routes_json",
			Value: node.Canonical(),
		}},
	}); err != nil {
		return err
	}

	<-stream.Context().Done()
	return stream.Context().Err()
}

func routeTable() string {
	rateText := os.Getenv("ROUTE_RATE_BYTES_PER_SECOND")
	burstText := os.Getenv("ROUTE_BURST_BYTES")
	if rateText == "" || burstText == "" {
		return routes.DefaultJSON
	}

	rate, err := strconv.ParseInt(rateText, 10, 64)
	if err != nil {
		panic(err)
	}
	burst, err := strconv.ParseInt(burstText, 10, 64)
	if err != nil {
		panic(err)
	}

	var table struct {
		Version int                      `json:"version"`
		Routes  []map[string]interface{} `json:"routes"`
	}
	if err = json.Unmarshal([]byte(routes.DefaultJSON), &table); err != nil {
		panic(err)
	}
	for _, route := range table.Routes {
		route["upload_bytes_per_second"] = rate
		route["download_bytes_per_second"] = rate
		route["burst_bytes"] = burst
	}

	encoded, err := json.Marshal(table)
	if err != nil {
		panic(err)
	}
	return string(encoded)
}

