package httpproxy

import (
	"context"
	"errors"
	"fmt"
	"io"
	"net"
	"net/http"
	"strconv"
	"strings"
	"syscall"

	"gitlab.wildberries.ru/pmg/pmg/mikrotik/internal/metrics"
	"gitlab.wildberries.ru/pmg/pmg/mikrotik/internal/models"
	"gitlab.wildberries.ru/pmg/pmg/mikrotik/internal/types"
)

const (
	modeHTTP             = "http"
	modeCONNECT          = "connect"
	unknownRoute         = "unknown"
	outcomeStreamFailure = "stream_failure"
)

type requestHandler struct {
	routes      routeRegistry
	credentials credentials
	limiter     limiter
	connector   connector
	tunnels     *tunnelSet
}

func newRequestHandler(dependencies Dependencies, tunnels *tunnelSet) *requestHandler {
	return &requestHandler{
		routes:      dependencies.Routes,
		credentials: dependencies.Credentials,
		limiter:     dependencies.Limiter,
		connector:   dependencies.Connector,
		tunnels:     tunnels,
	}
}

func (h *requestHandler) ServeHTTP(writer http.ResponseWriter, request *http.Request) {
	if request.ProtoMajor != 1 || request.ProtoMinor != 1 {
		metrics.RecordOutcome(request.Context(), unknownRoute, requestMode(request), "unsupported_protocol")
		http.Error(writer, "HTTP/1.1 required", http.StatusHTTPVersionNotSupported)
		return
	}

	routeID, authenticated := h.credentials.Authenticate(request.Header.Get("Proxy-Authorization"))
	if !authenticated {
		h.rejectAuthentication(writer, request, unknownRoute)
		return
	}

	route, exists := h.routes.Lookup(routeID)
	if !exists {
		h.rejectAuthentication(writer, request, unknownRoute)
		return
	}

	if request.Method == http.MethodConnect {
		h.serveConnect(writer, request, route)
		return
	}

	h.serveHTTP(writer, request, route)
}

func (h *requestHandler) serveConnect(writer http.ResponseWriter, request *http.Request, route *models.Route) {
	if err := validateDestination(request.Host); err != nil {
		metrics.RecordOutcome(request.Context(), route.ID, modeCONNECT, "invalid_target")
		http.Error(writer, "bad gateway", http.StatusBadGateway)
		return
	}

	upstream, err := h.connector.Dial(request.Context(), route, request.Host)
	if err != nil {
		metrics.RecordOutcome(request.Context(), route.ID, modeCONNECT, "destination_failure")
		http.Error(writer, "bad gateway", http.StatusBadGateway)
		return
	}

	hijacker, ok := writer.(http.Hijacker)
	if !ok {
		_ = upstream.Close()
		metrics.RecordOutcome(request.Context(), route.ID, modeCONNECT, "hijack_unsupported")
		http.Error(writer, "proxy tunneling unavailable", http.StatusInternalServerError)
		return
	}

	client, buffered, err := hijacker.Hijack()
	if err != nil {
		_ = upstream.Close()
		metrics.RecordOutcome(request.Context(), route.ID, modeCONNECT, "hijack_failure")
		return
	}

	active := &tunnel{client: client, upstream: upstream}
	if !h.tunnels.add(active) {
		active.close()
		return
	}
	defer func() {
		active.close()
		h.tunnels.remove(active)
	}()

	if _, err = buffered.WriteString("HTTP/1.1 200 Connection Established\r\n\r\n"); err != nil {
		metrics.RecordOutcome(request.Context(), route.ID, modeCONNECT, "client_failure")
		return
	}
	if err = buffered.Flush(); err != nil {
		metrics.RecordOutcome(request.Context(), route.ID, modeCONNECT, "client_failure")
		return
	}

	metrics.AddActiveTunnel(request.Context(), route.ID, 1)
	defer metrics.AddActiveTunnel(request.Context(), route.ID, -1)

	copier := newPacedCopier(route, modeCONNECT, h.limiter)
	results := make(chan error, 2)
	go func() {
		copyErr := copier.copy(request.Context(), upstream, buffered.Reader, types.DirectionUpload, nil)
		halfCloseWrite(upstream)
		results <- copyErr
	}()
	go func() {
		copyErr := copier.copy(request.Context(), client, upstream, types.DirectionDownload, nil)
		halfCloseWrite(client)
		results <- copyErr
	}()

	firstErr := <-results
	if firstErr != nil {
		active.close()
	}
	secondErr := <-results

	outcome := tunnelOutcome(firstErr, secondErr)
	metrics.RecordOutcome(request.Context(), route.ID, modeCONNECT, outcome)
}

func (h *requestHandler) serveHTTP(writer http.ResponseWriter, request *http.Request, route *models.Route) {
	outgoing := request.Clone(request.Context())
	outgoing.RequestURI = ""
	removeHopByHopHeaders(outgoing.Header)
	outgoing.Close = false

	if outgoing.URL.Scheme == "" {
		outgoing.URL.Scheme = "http"
	}
	if outgoing.URL.Host == "" {
		outgoing.URL.Host = request.Host
	}
	if !strings.EqualFold(outgoing.URL.Scheme, "http") || outgoing.URL.Host == "" {
		metrics.RecordOutcome(request.Context(), route.ID, modeHTTP, "invalid_target")
		http.Error(writer, "invalid HTTP proxy target", http.StatusBadRequest)
		return
	}

	copier := newPacedCopier(route, modeHTTP, h.limiter)
	outgoing.Host = request.Host
	if outgoing.Body != nil && outgoing.Body != http.NoBody {
		outgoing.Body = copier.wrapBody(request.Context(), outgoing.Body, types.DirectionUpload)
	}

	response, err := h.connector.Transport(route).RoundTrip(outgoing)
	if err != nil {
		if response != nil && response.Body != nil {
			_ = response.Body.Close()
		}

		metrics.RecordOutcome(request.Context(), route.ID, modeHTTP, "destination_failure")
		http.Error(writer, "bad gateway", http.StatusBadGateway)
		return
	}
	defer response.Body.Close()

	removeHopByHopHeaders(response.Header)
	copyHeaders(writer.Header(), response.Header)
	writer.WriteHeader(response.StatusCode)

	var flush func()
	if flusher, ok := writer.(http.Flusher); ok {
		flush = flusher.Flush
	}

	err = copier.copy(request.Context(), writer, response.Body, types.DirectionDownload, flush)
	if err != nil {
		if isBenignTunnelError(err) {
			metrics.RecordOutcome(request.Context(), route.ID, modeHTTP, "closed")
			return
		}

