func (h *requestHandler) rejectAuthentication(
	writer http.ResponseWriter,
	request *http.Request,
	routeID string,
) {
	writer.Header().Set("Proxy-Authenticate", h.credentials.Challenge())
	metrics.RecordOutcome(request.Context(), routeID, requestMode(request), "authentication_failure")
	http.Error(writer, "proxy authentication required", http.StatusProxyAuthRequired)
}

func validateDestination(destination string) error {
	host, portText, err := net.SplitHostPort(destination)
	if err != nil {
		return fmt.Errorf("split destination: %w", err)
	}
	if host == "" {
		return errors.New("destination host is empty")
	}

	port, err := strconv.Atoi(portText)
	if err != nil || port < 1 || port > 65535 {
		return fmt.Errorf("invalid destination port %q", portText)
	}

	return nil
}

func requestMode(request *http.Request) string {
	if request.Method == http.MethodConnect {
		return modeCONNECT
	}

	return modeHTTP
}

func tunnelOutcome(errs ...error) string {
	for _, err := range errs {
		if err != nil && !isBenignTunnelError(err) {
			return outcomeStreamFailure
		}
	}

	return "closed"
}

func isBenignTunnelError(err error) bool {
	return errors.Is(err, io.EOF) ||
		errors.Is(err, net.ErrClosed) ||
		errors.Is(err, context.Canceled) ||
		errors.Is(err, syscall.ECONNRESET) ||
		errors.Is(err, syscall.EPIPE)
}

