	defer metrics.AddActiveTunnel(request.Context(), route.ID, -1)

	copier := newPacedCopier(route, modeCONNECT, h.limiter)
	results := make(chan error, 2)
	go func() {
		copyErr := copier.copy(request.Context(), upstream, buffered.Reader, types.DirectionUpload, nil)
		halfCloseWrite(upstream)
		results <- copyErr
	}()
	go func() {
		copyErr := copier.copy(request.Context(), client, upstream, types.DirectionDownload, nil)
		halfCloseWrite(client)
		results <- copyErr
	}()

	firstErr := <-results
	if firstErr != nil {
