		return errors.New("destination host is empty")
	}

	port, err := strconv.Atoi(portText)
	if err != nil || port < 1 || port > 65535 {
		return fmt.Errorf("invalid destination port %q", portText)
	}

	return nil
}

func requestMode(request *http.Request) string {
	if request.Method == http.MethodConnect {
		return modeCONNECT
	}

	return modeHTTP
}

func tunnelOutcome(errs ...error) string {
	for _, err := range errs {
		if err != nil && !isBenignTunnelError(err) {
			return outcomeStreamFailure
		}
	}

	return "closed"
}

func isBenignTunnelError(err error) bool {
	return errors.Is(err, io.EOF) ||
		errors.Is(err, net.ErrClosed) ||
		errors.Is(err, context.Canceled) ||
		errors.Is(err, syscall.ECONNRESET) ||
		errors.Is(err, syscall.EPIPE)
}

