package httpproxy

import (
	"context"
	"errors"
	"io"
	"net"
	"sync"

	"gitlab.wildberries.ru/pmg/pmg/mikrotik/internal/metrics"
	"gitlab.wildberries.ru/pmg/pmg/mikrotik/internal/models"
	"gitlab.wildberries.ru/pmg/pmg/mikrotik/internal/types"
)

// trafficChunkSize bounds each transfer so bandwidth reservations stay small
// and pacing remains smooth.
const trafficChunkSize = 32 * 1024

type pacedCopier struct {
	route   *models.Route
	mode    string
	limiter limiter
}

func newPacedCopier(route *models.Route, mode string, limiter limiter) *pacedCopier {
	return &pacedCopier{route: route, mode: mode, limiter: limiter}
}

func (p *pacedCopier) copy(
	ctx context.Context,
	destination io.Writer,
	source io.Reader,
	direction types.Direction,
	flush func(),
) error {
	buffer := make([]byte, trafficChunkSize)

	for {
		count, readErr := source.Read(buffer)
		if count > 0 {
			if err := p.limiter.Wait(ctx, p.route, direction, count); err != nil {
				return err
			}

			written, writeErr := destination.Write(buffer[:count])
			if written > 0 {
				metrics.AddBytes(ctx, p.route.ID, p.mode, direction, int64(written))
			}
			if writeErr != nil {
				return writeErr
			}
			if written < count {
				return io.ErrShortWrite
			}
			if flush != nil {
				flush()
			}
		}

		switch {
		case errors.Is(readErr, io.EOF):
			return nil
		case readErr != nil:
			return readErr
		}
	}
}

func (p *pacedCopier) wrapBody(
	ctx context.Context,
	body io.ReadCloser,
	direction types.Direction,
) io.ReadCloser {
	return &pacedReadCloser{context: ctx, body: body, copier: p, direction: direction}
}

type pacedReadCloser struct {
	context   context.Context
	body      io.ReadCloser
	copier    *pacedCopier
	direction types.Direction
}

func (r *pacedReadCloser) Read(buffer []byte) (int, error) {
	if len(buffer) > trafficChunkSize {
		buffer = buffer[:trafficChunkSize]
	}

	count, readErr := r.body.Read(buffer)
	if count > 0 {
		if err := r.copier.limiter.Wait(r.context, r.copier.route, r.direction, count); err != nil {
			return 0, err
		}
		metrics.AddBytes(r.context, r.copier.route.ID, r.copier.mode, r.direction, int64(count))
	}

	return count, readErr
}

func (r *pacedReadCloser) Close() error {
	return r.body.Close()
}

type tunnel struct {
	client   net.Conn
	upstream net.Conn
	once     sync.Once
}

func (t *tunnel) close() {
	t.once.Do(func() {
		_ = t.client.Close()
		_ = t.upstream.Close()
	})
}

type tunnelSet struct {
	mu      sync.Mutex
	closing bool
	active  map[*tunnel]struct{}
	wait    sync.WaitGroup
}

func newTunnelSet() *tunnelSet {
	return &tunnelSet{active: make(map[*tunnel]struct{})}
}

func (s *tunnelSet) add(value *tunnel) bool {
	s.mu.Lock()
	defer s.mu.Unlock()

	if s.closing {
		return false
	}

	s.active[value] = struct{}{}
	s.wait.Add(1)
	return true
}

func (s *tunnelSet) remove(value *tunnel) {
	s.mu.Lock()
	delete(s.active, value)
	s.mu.Unlock()
	s.wait.Done()
}

func (s *tunnelSet) closeAll() {
	s.mu.Lock()
	s.closing = true
	active := make([]*tunnel, 0, len(s.active))
	for value := range s.active {
		active = append(active, value)
	}
	s.mu.Unlock()

	for _, value := range active {
		value.close()
	}
}

func (s *tunnelSet) waitForClose(ctx context.Context) error {
	done := make(chan struct{})
	go func() {
		s.wait.Wait()
		close(done)
	}()

	select {
	case <-done:
		return nil
	case <-ctx.Done():
		return ctx.Err()
	}
}

func halfCloseWrite(connection io.Writer) {
	if writer, ok := connection.(interface{ CloseWrite() error }); ok {
		_ = writer.CloseWrite()
	}
}

