package httpproxy

import (
	"context"
	"errors"
	"io"
	"net/http"
	"net/http/httptest"
	"syscall"
	"testing"
)

// failingBody fails its first read, standing in for a request body whose
// pacing reservation was rejected by the bandwidth scheduler.
type failingBody struct{ err error }

func (b *failingBody) Read([]byte) (int, error) { return 0, b.err }
func (b *failingBody) Close() error             { return nil }

// TestRoundTripOutcomeSurvivesTransport pins the assumption the outcome
// classification rests on: net/http hands a request body error back from
// RoundTrip with its error chain intact.
func TestRoundTripOutcomeSurvivesTransport(t *testing.T) {
	server := httptest.NewServer(http.HandlerFunc(func(_ http.ResponseWriter, request *http.Request) {
		_, _ = io.Copy(io.Discard, request.Body)
	}))
	defer server.Close()

	tests := []struct {
		name  string
		cause error
		want  string
	}{
		{
			name:  "scheduler outage",
			cause: throttleFailure(errors.New("reserve bandwidth: redis unavailable")),
			want:  outcomeThrottleFailure,
		},
		{
			name:  "client vanished while throttled",
			cause: throttleFailure(context.Canceled),
			want:  outcomeClosed,
		},
		{
			name:  "destination reset the connection",
			cause: syscall.ECONNRESET,
			want:  outcomeDestinationFailure,
		},
	}

	for _, test := range tests {
		t.Run(test.name, func(t *testing.T) {
			request, err := http.NewRequest(http.MethodPost, server.URL, &failingBody{err: test.cause})
			if err != nil {
				t.Fatalf("build request: %v", err)
			}
			request.ContentLength = -1

			transport := &http.Transport{}
			defer transport.CloseIdleConnections()

			response, err := transport.RoundTrip(request)
			if response != nil {
				_ = response.Body.Close()
			}
			if err == nil {
				t.Fatal("expected RoundTrip to fail")
			}
			if got := roundTripOutcome(err); got != test.want {
				t.Fatalf("roundTripOutcome = %q, want %q (error: %v)", got, test.want, err)
			}
		})
	}
}

func TestTunnelOutcome(t *testing.T) {
	tests := []struct {
		name string
		errs []error
		want string
	}{
		{name: "both directions clean", errs: []error{nil, nil}, want: outcomeClosed},
		{name: "benign disconnect", errs: []error{nil, io.EOF}, want: outcomeClosed},
		{name: "network failure", errs: []error{nil, errors.New("broken pipe upstream")}, want: outcomeStreamFailure},
		{
			name: "scheduler outage outranks the failure it caused",
			errs: []error{throttleFailure(errors.New("redis unavailable")), errors.New("use of closed connection")},
			want: outcomeThrottleFailure,
		},
		{
			name: "throttled client disconnect stays benign",
			errs: []error{throttleFailure(context.Canceled), nil},
			want: outcomeClosed,
		},
	}

	for _, test := range tests {
		t.Run(test.name, func(t *testing.T) {
			if got := tunnelOutcome(test.errs...); got != test.want {
				t.Fatalf("tunnelOutcome = %q, want %q", got, test.want)
			}
		})
	}
}

